package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import thaumcraft.api.aspects.*;
import thaumcraft.api.research.*;
final class KamiMaterialAudit {
 private static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT KAMI materials: "+label);}
 static void run(){
  String[] keys={"ICHOR_CLOTH","ICHORIUM","CAP_ICHOR","ROD_ICHORCLOTH"},parents={"ICHOR","ICHOR","ICHORIUM","ICHOR_CLOTH"};int[] xs={11,11,11,14},ys={7,9,11,2};
  for(int i=0;i<4;i++){var r=ResearchCategories.getResearch(keys[i]);check(r instanceof KamiResearch&&r.isConcealed()&&r.displayColumn==xs[i]&&r.displayRow==ys[i]&&java.util.Arrays.equals(r.parents,new String[]{parents[i]}),"original coordinates/parent "+keys[i]);check(r.getPages().length==2&&r.getPages()[0].text.equals("ttresearch.page."+keys[i]+".0")&&r.getPages()[1].recipeKey.equals(keys[i]),"original text and recipe pages");var done=new java.util.HashSet<>(java.util.Arrays.asList(r.parentsHidden));done.add(parents[i]);check(dev.eugheist.tc4modern.ResearchProgress.requisites(done,r),"full gate allows "+keys[i]);done.remove(parents[i]);check(!dev.eugheist.tc4modern.ResearchProgress.requisites(done,r),"visible parent required "+keys[i]);}
  check(java.util.Arrays.asList(ResearchCategories.getResearch("ICHORIUM").parentsHidden).contains("ICHOR_CLOTH")&&java.util.Arrays.asList(ResearchCategories.getResearch("ROD_ICHORCLOTH").parentsHidden).contains("CAP_ICHOR"),"original explicit hidden cloth/cap gates");check(dev.eugheist.tc4modern.ResearchWarp.amount("CAP_ICHOR")==2&&dev.eugheist.tc4modern.ResearchWarp.amount("ROD_ICHORCLOTH")==1,"original warp values");
  KamiResources.Kind[] outputs={KamiResources.Kind.CLOTH,KamiResources.Kind.ICHORIUM,KamiResources.Kind.CAP};int[] counts={3,1,2},costs={125,100,100};
  for(int i=0;i<3;i++){final String key=keys[i];var r=dev.eugheist.tc4modern.ArcaneRecipes.entries().stream().filter(x->x.key().equals(key)).findFirst().orElseThrow();check(r.width()==3&&r.height()==3&&r.output().is(KamiResources.item(outputs[i]))&&r.output().getCount()==counts[i]&&r.cost().size()==6,"original arcane dimensions/output "+key);for(var a:Aspect.getPrimalAspects())check(r.cost().getAmount(a)==costs[i],"six primal vis costs "+key);var grid=new java.util.ArrayList<ItemStack>();for(var ingredient:r.ingredients())grid.add(ingredient.isEmpty()?ItemStack.EMPTY:ingredient.getItems()[0].copy());check(dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of(key))==r&&dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of())==null,"actual arcane match/research gate "+key);grid.set(4,new ItemStack(Items.DIRT));check(!r.matches(grid,java.util.Set.of(key)),"wrong center rejected "+key);}
  var cap=dev.eugheist.tc4modern.ArcaneRecipes.entries().stream().filter(x->x.key().equals("CAP_ICHOR")).findFirst().orElseThrow();check(cap.ingredients().get(1).test(new ItemStack(dev.eugheist.tc4modern.WandParts.THAUMIUM_CAP.get()))&&!cap.ingredients().get(1).test(new ItemStack(dev.eugheist.tc4modern.WandParts.THAUMIUM_CAP_INERT.get())),"original meta2 is charged thaumium cap");
  var rod=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(x->x.key().equals("ROD_ICHORCLOTH")).findFirst().orElseThrow();check(rod.instability()==9&&rod.aspects().size()==3&&rod.aspects().getAmount(Aspect.MAGIC)==100&&rod.aspects().getAmount(Aspect.LIGHT)==32&&rod.aspects().getAmount(Aspect.TOOL)==32&&rod.central().get()==dev.eugheist.tc4modern.WandParts.RODS.get("silverwood").get(),"original rod infusion central/cost");var parts=rod.componentStacks();check(parts.size()==6&&parts.get(0).is(KamiResources.item(KamiResources.Kind.ICHOR))&&parts.get(1).is(KamiResources.item(KamiResources.Kind.CLOTH))&&parts.get(2).is(FocusResearch.item("salis_mundus"))&&parts.get(3).is(Items.GHAST_TEAR)&&parts.get(4).is(FocusResearch.item("salis_mundus"))&&parts.get(5).is(KamiResources.item(KamiResources.Kind.CLOTH)),"original six rod components/order");var input=new ItemStack(rod.central().get());check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of("ROD_ICHORCLOTH"))==rod&&dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of())==null&&rod.outputStack(input).is(KamiResources.item(KamiResources.Kind.ROD)),"native rod infusion/research/output");
  System.out.println("TT KAMI MATERIAL AUDIT: ALL PASS (four original research gates/pages/warp,three native arcane recipes/six primal costs,charged caps,rod native infusion)");
 }
}
